const items = $input.all();
const cleanedItems = [];

for (const item of items) {
    const rawData = item.json;

    // Extract sender email and name safely
    let senderEmail = "";
    let senderName = "";
    if (rawData.from && rawData.from.value && rawData.from.value.length > 0) {
        senderEmail = rawData.from.value[0].address || "";
        senderName = rawData.from.value[0].name || "";
    }

    // Clean the subject (Gmail sometimes prepends 'Subject: ')
    let cleanSubject = rawData.subject || "";
    if (cleanSubject.startsWith("Subject: ")) {
        cleanSubject = cleanSubject.substring(9);
    }

    // Clean the body text
    let rawText = rawData.text || "";
    let cleanText = rawText
        .replace(/\r\n/g, " ")   // Replace carriage returns
        .replace(/\n/g, " ")     // Replace newlines
        .replace(/\s\s+/g, " ")  // Replace multiple spaces with a single space
        .trim();                 // Remove leading/trailing spaces

    // Push the formatted data to the output
    cleanedItems.push({
        json: {
            message_id: rawData.id,
            date: rawData.date,
            subject: cleanSubject.trim(),
            sender_email: senderEmail,
            sender_name: senderName,
            email_body_clean: cleanText
        }
    });
}

return cleanedItems;

