// 1. Get the raw text response from Agent 2
const agent2RawContent = $input.first().json.choices[0].message.content;

// 2. Parse the text into a real JavaScript object
let agent2Data;
try {
    agent2Data = JSON.parse(agent2RawContent);
} catch (error) {
    throw new Error("Failed to parse Agent 2 JSON. AI might have hallucinated formatting.");
}

// 3. Fetch the original clean email data
const emailData = $('Email Cleaner').first().json;

// 4. RULE EVALUATION (Deterministic Logic)
// Rule A: Intent must be valid
const isIntentValid = agent2Data.hiring_intent_valid === true;
// Rule B: Category must be one of the explicitly approved recruitment categories
const allowedCategories = [
    "recruitment_company_email",
    "recruitment_personal_email",
    "interview_invite",
    "assessment_invite",
    "offer_letter",
    "application_confirmation",
    "rejection",
    "job_alert_linkedin",
    "job_alert_naukri",
    "job_alert_indeed",
    "job_alert_foundit"
];
const isValidCategory = allowedCategories.includes(agent2Data.final_category);

// 5. DECISION
if (isIntentValid && isValidCategory) {
    // If it passes the rules, we bundle everything together and send it forward
    return [
        {
            json: {
                message_id: emailData.message_id,
                date: emailData.date,
                subject: emailData.subject,
                sender_email: emailData.sender_email,
                sender_name: emailData.sender_name,
                email_body_clean: emailData.email_body_clean,
                final_category: agent2Data.final_category,
                validation_reason: agent2Data.validation_reason,
                status: "APPROVED_FOR_EXTRACTION"
            }
        }
    ];
} else {
    // If it fails the rules we return an empty array.
    // In n8n, returning an empty array STOPS the workflow execution for this branch.
    return [];
}

const items = $input.all();
const processedItems = [];

// List of common public/free email providers to check against
const publicDomains = [
    'gmail.com', 'yahoo.com', 'outlook.com', 'hotmail.com', 
    'live.com', 'icloud.com', 'zoho.com', 'proton.me', 'protonmail.com'
];

for (const item of items) {
    const data = item.json;
    const category = data.final_category || "";
    const email = data.sender_email || "";
    const domain = email.split('@')[1] ? email.split('@')[1].toLowerCase() : "";

    let platformSource = "other";

    // 1. Direct platform alert matching
    if (category === "job_alert_linkedin") {
        platformSource = "linkedin";
    } else if (category === "job_alert_naukri") {
        platformSource = "naukri";
    } else if (category === "job_alert_indeed") {
        platformSource = "indeed";
    } else if (category === "job_alert_foundit") {
        platformSource = "foundit";
    } 
    // 2. Direct recruiter matching based on email classification
    else if (category === "recruitment_company_email") {
        platformSource = "company_direct";
    } else if (category === "recruitment_personal_email") {
        platformSource = "company_email";
    }
    // 3. Fallback routing for transactional states (invites, updates, offers)
    else if (["interview_invite", "assessment_invite", "offer_letter", "application_confirmation", "rejection"].includes(category)) {
        if (publicDomains.includes(domain)) {
            platformSource = "company_email"; // Sent by an individual from a public account
        } else {
            platformSource = "company_direct"; // Sent from an official corporate domain
        }
    }

    // Append the detected platform source to our data packet
    processedItems.push({
        json: {
            ...data,
            platform_source: platformSource
        }
    });
}

return processedItems;

