// 1. Get the raw response from the Job Extractor node
const inputData = $input.first().json;
const extractorRawContent = inputData.choices[0].message.content;

// 2. Parse the stringified text into a real object
let extractorData;
try {
    extractorData = JSON.parse(extractorRawContent);
} catch (error) {
    throw new Error("Failed to parse Job Extractor JSON payload.");
}

const jobsArray = extractorData.jobs || [];

// 3. Fetch parent metadata from the Platform Detector node
const parentMetadata = $('Platform Detector').first().json;

const updatedItems = [];

// 4. Transform the array into individual n8n items
for (const job of jobsArray) {
    updatedItems.push({
        json: {
            message_id: parentMetadata.message_id,
            email_date: parentMetadata.date,
            platform_source: parentMetadata.platform_source,
            final_category: parentMetadata.final_category,
            company: job.company || "Unknown Company",
            role: job.role || "Unknown Role",
            location: job.location || null
        }
    });
}

return updatedItems;

// 1. Fetch ALL items from the 'Split Jobs' node to ensure we process every job
const splitJobsItems = $('Split Jobs').all();

// Safety check: ensure the data is in memory
if (!splitJobsItems || splitJobsItems.length === 0) {
    throw new Error("No data found in 'Split Jobs'. Please go back and click 'Test step' on Node 8, then immediately test this node.");
}

const dashboardItems = [];

for (const item of splitJobsItems) {
    const sourceJob = item.json;

    // 2. Format localized presentation fields
    const rawDate = new Date(sourceJob.email_date);
    const formattedDisplayDate = isNaN(rawDate.getTime()) 
        ? "Recent" 
        : rawDate.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });

    // 3. Apply structural casing normalization to properties
    const cleanCompany = (sourceJob.company || "Unknown").replace(/\s+/g, ' ').trim();
    const cleanRole = (sourceJob.role || "Unknown").replace(/\s+/g, ' ').trim();
    const cleanLocation = sourceJob.location ? sourceJob.location.trim() : "Not Specified";

    // 4. Calculate an analytical pipeline priority metric based on category
    let structuralPriority = "MEDIUM";
    if (["interview_invite", "offer_letter"].includes(sourceJob.final_category)) {
        structuralPriority = "HIGH";
    } else if (["rejection", "other_reject"].includes(sourceJob.final_category)) {
        structuralPriority = "LOW";
    }

    // 5. Construct the final dashboard-ready contract
    dashboardItems.push({
        json: {
            tracker_id: sourceJob.message_id,
            display_date: formattedDisplayDate,
            origin_platform: sourceJob.platform_source,
            classification: sourceJob.final_category,
            company_display: cleanCompany,
            role_display: cleanRole,
            location_display: cleanLocation,
            pipeline_priority: structuralPriority,
            processed_timestamp: new Date().toISOString()
        }
    });
}

return dashboardItems;

const items = $input.all();
const alertResults = [];

for (const item of items) {
    const data = item.json;
    const priority = data.pipeline_priority || "MEDIUM";
    const classification = data.classification || "";

    // RULE: Only trigger alerts for actionable metrics (High & Medium priority)
    // Do not trigger alerts for rejections or standard confirmation noise
    const isActionable = priority === "HIGH" || priority === "MEDIUM";
    const isNotRejection = !["rejection", "other_reject"].includes(classification);

    if (isActionable && isNotRejection) {
        // Construct a clean presentation notification string
        const alertMessage = `🚨 NEW RECRUITMENT OPPORTUNITY DETECTED 🚨\n\n` +
                             `• Role: ${data.role_display}\n` +
                             `• Company: ${data.company_display}\n` +
                             `• Location: ${data.location_display}\n` +
                             `• Source Platform: ${data.origin_platform.toUpperCase()}\n` +
                             `• Priority Level: ${priority}\n` +
                             `• Date Received: ${data.display_date}\n\n` +
                             `System Tracking ID: ${data.tracker_id}`;

        alertResults.push({
            json: {
                alert_triggered: true,
                dispatch_timestamp: new Date().toISOString(),
                target_priority: priority,
                notification_subject: `[Job Alert] ${data.role_display} at ${data.company_display}`,
                notification_body: alertMessage,
                tracker_id: data.tracker_id
            }
        });
    } else {
        // Log entry indicating the item bypassed the notification protocol safely
        alertResults.push({
            json: {
                alert_triggered: false,
                reason: `Item classified as ${classification} (${priority} priority). Notification bypassed.`,
                tracker_id: data.tracker_id
            }
        });
    }
}

return alertResults;
